SELECT * FROM (SELECT e.event_id,'P:'||s.plate_id case_id,e.activity,e.timestamp FROM (SELECT 'PLATE:'||plate_id||':identified' event_id,'Plate Identified' activity,identified_at timestamp,plate_id source_key FROM plate_material WHERE identified_at IS NOT NULL AND (1=1)) e JOIN plate_material s ON s.plate_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.mother_material_id UNION ALL SELECT e.event_id,'P:'||s.plate_id case_id,e.activity,e.timestamp FROM (SELECT 'PLATE:'||plate_id||':released' event_id,'Plate Released' activity,released_at timestamp,plate_id source_key FROM plate_material WHERE released_at IS NOT NULL AND (1=1)) e JOIN plate_material s ON s.plate_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.mother_material_id UNION ALL SELECT e.event_id,'P:'||s.plate_id case_id,e.activity,e.timestamp FROM (SELECT 'PLATE:'||plate_id||':packed' event_id,'Plate Packed' activity,packed_at timestamp,plate_id source_key FROM plate_material WHERE packed_at IS NOT NULL AND (1=1)) e JOIN plate_material s ON s.plate_id=e.source_key JOIN as_rolled_material m ON m.material_id=s.mother_material_id) ORDER BY case_id,timestamp,event_id;
